// Complete days (before today) with a live partition and no aggregate yet.
func (q *Queries) ListDaysToAggregate(ctx context.Context, today pgtype.Date) ([]pgtype.Date, error) {
	rows, err := q.db.Query(ctx, listDaysToAggregate, today)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []pgtype.Date
	for rows.Next() {
		var day pgtype.Date
		if err := rows.Scan(&day); err != nil {
			return nil, err
		}
		items = append(items, day)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

