func (q *Queries) UpsertFirstSeen(ctx context.Context, day pgtype.Date) (int64, error) {
	result, err := q.db.Exec(ctx, upsertFirstSeen, day)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
